  3953  static inline uint8_t *skip_aux(uint8_t *s, uint8_t *end)
  3954  {
  3955      int size;
  3956      uint32_t n;
  3957      if (s >= end) return end;
  3958      size = aux_type2size(*s); ++s; // skip type
  3959      switch (size) {
  3960      case 'Z':
  3961      case 'H':
  3962          while (s < end && *s) ++s;
  3963          return s < end ? s + 1 : end;
  3964      case 'B':
  3965          if (end - s < 5) return NULL;
  3966          size = aux_type2size(*s); ++s;
  3967          n = le_to_u32(s);
  3968          s += 4;
  3969          if (size == 0 || end - s < size * n) return NULL;
  3970          return s + size * n;
  3971      case 0:
  3972          return NULL;
  3973      default:
  3974          if (end - s < size) return NULL;
  3975          return s + size;
  3976      }
  3977  }
